<!-- wp:image {"className":"fr-story-chapter-image"} --><figure class="wp-block-image fr-story-chapter-image"><img src="https://fatherpeyton.org/wp-content/uploads/sites/5/2025/08/Life-of-Christ-filming.webp" alt="A film crew working with a motion picture camera on the Life of Christ production."/><figcaption class="wp-element-caption">Filming the mysteries of the Rosary.</figcaption></figure><!-- /wp:image -->

</div><!-- /wp:group -->

</section><!-- /wp:group -->
